using System.Globalization;using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;namespace DirectorFamilyTravelDesk.Views;public partial class FlightsView:UserControl,IRefreshable{private long _id;private List<FlightItem> _all=new();public FlightsView(){InitializeComponent();}public void RefreshData(){var r=App.Repository.GetRoutes(false);RouteBox.ItemsSource=r;FilterRoute.ItemsSource=new[]{new RouteItem{Id=0,RouteLabel="All Routes"}}.Concat(r).ToList();FilterRoute.SelectedValue=0L;_all=App.Repository.GetAllFlights();Grid.ItemsSource=_all;}private void FilterRoute_Changed(object s,SelectionChangedEventArgs e){if(!IsLoaded)return;var id=FilterRoute.SelectedValue is long routeId ? routeId : 0L;Grid.ItemsSource=id==0?_all:_all.Where(x=>x.RouteId==id).ToList();}private void Grid_SelectionChanged(object s,SelectionChangedEventArgs e){if(Grid.SelectedItem is FlightItem x){_id=x.Id;AirlineBox.Text=x.Airline;FlightNoBox.Text=x.FlightNo;RouteBox.SelectedValue=x.RouteId;DepBox.Text=x.DepartureTime;ArrBox.Text=x.ArrivalTime;StopsBox.Text=x.Stops.ToString();ViaBox.Text=x.ViaIata;ActiveBox.IsChecked=x.IsActive;}}private void Save_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(AirlineBox.Text)||string.IsNullOrWhiteSpace(FlightNoBox.Text)||RouteBox.SelectedValue is not long rid||!TimeSpan.TryParseExact(DepBox.Text,"hh\\:mm",CultureInfo.InvariantCulture,out _)||!TimeSpan.TryParseExact(ArrBox.Text,"hh\\:mm",CultureInfo.InvariantCulture,out _)){MessageBox.Show("Enter Airline, Flight No, Route and valid HH:mm times.");return;}int.TryParse(StopsBox.Text,out var stops);try{App.Repository.SaveFlight(new(){Id=_id,Airline=AirlineBox.Text,FlightNo=FlightNoBox.Text,RouteId=rid,DepartureTime=DepBox.Text,ArrivalTime=ArrBox.Text,Stops=Math.Max(0,stops),ViaIata=ViaBox.Text.Trim().ToUpperInvariant(),IsActive=ActiveBox.IsChecked==true});_id=0;AirlineBox.Text=FlightNoBox.Text=DepBox.Text=ArrBox.Text=ViaBox.Text="";StopsBox.Text="0";RouteBox.SelectedIndex=-1;ActiveBox.IsChecked=true;RefreshData();}catch(Exception ex){MessageBox.Show(ex.Message);}}}